    // Remove spaces
    expr = expr.replace(/\s+/g, '');

    // Tokenize the expression
    const tokens = [];
    let numberBuffer = '';
    for (let i = 0; i < expr.length; i++) {
        const char = expr[i];
        if (/\d|\./.test(char)) {
            numberBuffer += char;
        } else {
            if (numberBuffer.length > 0) {
                tokens.push(parseFloat(numberBuffer));
                numberBuffer = '';
            }
            tokens.push(char);
        }
    }
    if (numberBuffer.length > 0) {
        tokens.push(parseFloat(numberBuffer));
    }

    // Helper function to apply an operator
    function applyOperator(operators, values) {
        const operator = operators.pop();
        const right = values.pop();
        const left = values.pop();
        switch (operator) {
            case '+':
                values.push(left + right);
                break;
            case '-':
                values.push(left - right);
                break;
            case '*':
                values.push(left * right);
                break;
            case '/':
                if (right === 0) {
                    throw new Error('Division by zero');
                }
                values.push(left / right);
                break;
            default:
                throw new Error('Unknown operator: ' + operator);
        }
    }

    // Operator precedence
    const precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2
    };

    const values = [];
    const operators = [];
for (const token of tokens) {
    if (typeof token === 'number') {
        values.push(token);
    } else if (token === '(') {
        operators.push(token);
    } else if (token === ')') {
        while (operators.length > 0 && operators[operators.length - 1] !== '(') {
            applyOperator(operators, values);
        }
        if (operators.length === 0 || operators.pop() !== '(') {
            throw new Error('Mismatched parentheses in expression: ' + expr);
        }
    } else if (token in precedence) {
        while (operators.length > 0 && precedence[operators[operators.length - 1]] >= precedence[token]) {
            applyOperator(operators, values);
        }
        operators.push(token);
    } else {
        throw new Error('Cannot parse expression: ' + expr);
    }
}

    while (operators.length > 0) {
        applyOperator(operators, values);
    }

    if (values.length !== 1) {
        throw new Error('Cannot parse expression: ' + expr);
    }

    return values[0];
}

