class Matrix {
constructor(rows) {
  if (!Array.isArray(rows) || rows.length === 0) {
    throw new Error('No rows provided');
  }

  const cols = rows[0].length;
  if (cols === 0) {
    throw new Error('Empty rows provided');
  }

  rows.forEach(row => {
    if (!Array.isArray(row) || row.length !== cols) {
