assert.strictEqual(evaluate('1 + 2'), 3);
assert.strictEqual(evaluate('3 - 2'), 1);
assert.strictEqual(evaluate('2 * 3'), 6);
assert.strictEqual(evaluate('6 / 2'), 3);
assert.strictEqual(evaluate('1 + 2 * 3'), 7); // Test precedence
